/* Textos do tutor para as 100 perguntas do Banco de Perguntas (57 com cena em banco.js, 43 em perguntas_sem_cena.js), versão para escolas.
   explicacao = a regra; artigo = base legal («A confirmar» = o instrutor indica; «Boa prática» = sem artigo);
   erradas    = o que o tutor mostra a quem escolhe cada opção errada (índice da opção em banco.js: 1 = B, 2 = C);
   exemplo    = o texto do botão «Dá-me um exemplo».
   Linguagem técnica, com os termos do Código da Estrada. Tudo por validar por um instrutor (BR-35). */
(function (global) {
  var E = {
    "1.1": ["Sem sinalização, cede-se a passagem a quem se apresenta pela direita. Ir em frente ou chegar primeiro não dá prioridade.", "Art. 30.º",
      { 1: "Seguir em frente não dá prioridade. Num cruzamento sem sinalização, cedes a passagem aos veículos que se apresentam pela tua direita.",
        2: "A ordem de chegada não dá prioridade. Mesmo que chegues primeiro, cedes a passagem ao veículo que se apresenta pela tua direita." },
      "A regra da direita vale nos cruzamentos e entroncamentos sem outra indicação. Havendo agente, semáforo ou sinal, são estes que decidem quem passa."],
    "1.2": ["Para o outro condutor, tu és quem vem da direita. A regra é a mesma, vista do outro lado.", "Art. 30.º",
      { 1: "Não tens de ceder. O ligeiro apresenta-se pela tua esquerda: para ele, és tu quem vem da direita, por isso é ele que cede a passagem.",
        2: "A prioridade resulta da regra e não de um acordo entre condutores. Parar sem necessidade cria incerteza: avanças, porque o outro condutor te deve ceder a passagem." },
      "Ter prioridade não dispensa a atenção. Antes de entrares no cruzamento, confirma que o outro condutor está a abrandar."],
    "1.3": ["Os sinais prevalecem sobre as regras gerais. Com STOP, paras sempre e cedes a quem circula na outra via, venha de onde vier.", "Art. 7.º, n.º 1",
      { 1: "O sinal STOP prevalece sobre a regra da direita. Depois de parar, cedes a passagem a todos os que circulam na via principal, venham da esquerda ou da direita.",
        2: "Com STOP, a paragem é obrigatória, mesmo que a via pareça livre ou o veículo esteja longe. Só avanças depois de parar e de confirmar que não obrigas ninguém a abrandar ou a desviar-se." },
      "STOP e cedência de passagem obrigam ambos a ceder. A diferença: com STOP paras sempre, mesmo sem trânsito; com cedência de passagem só paras se for necessário."],
    "1.4": ["O sinal de cedência obriga a ceder a todos os que circulam na via com prioridade. A regra da direita deixa de se aplicar.", "Art. 7.º, n.º 1",
      { 1: "O sinal de cedência de passagem prevalece sobre a regra da direita. Cedes a todos os veículos que circulam na via com prioridade, incluindo o que vem pela esquerda.",
        2: "A obrigação de ceder abrange os veículos dos dois lados. O ligeiro que vem pela direita também circula na via com prioridade." },
      "Hierarquia: as ordens dos agentes prevalecem sobre os sinais, e os sinais sobre as regras gerais, como a da direita. Entre sinais, os luminosos prevalecem sobre os verticais, e estes sobre as marcas na estrada."],
    "1.5": ["Quem muda de direção para a esquerda cede a passagem aos veículos que vêm em sentido contrário. O pisca avisa, mas não dá prioridade.", "A confirmar",
      { 1: "Sinalizar não dá prioridade. O pisca anuncia a mudança de direção, mas quem vira à esquerda cede a passagem aos veículos que circulam em sentido contrário.",
        2: "A posição no cruzamento não decide a prioridade. Ao mudar de direção para a esquerda, cedes a passagem ao trânsito que vem em sentido contrário." },
      "Enquanto esperas para virar, mantém as rodas direitas. Se fores embatido por trás, o carro não é empurrado para o trânsito em sentido contrário."],
    "2.1": ["Ao entrar, cede-se a passagem a quem já circula na rotunda, seja qual for a via em que esteja.", "Art. 14.º-A, n.º 1, al. a)",
      { 1: "À entrada da rotunda não se aplica a regra da direita. Quem entra cede a passagem aos veículos que já circulam na rotunda.",
        2: "Entrar obrigando quem circula na rotunda a abrandar é não ceder a passagem. Só entras quando não obrigas ninguém a alterar a velocidade ou a trajetória." },
      "A obrigação de ceder vale para quem circula em qualquer via da rotunda, interior ou exterior."],
    "2.2": ["Para sair na primeira saída, ocupa-se a via da direita.", "Art. 14.º-A, n.º 1, al. b)",
      { 1: "Para a primeira saída, ocupas a via da direita desde a entrada. Passar da via interior para a direita junto à saída corta a trajetória de quem lá circula.",
        2: "O pisca anuncia a manobra, mas não a torna correta. Para a primeira saída, a regra é ocupar a via da direita." },
      "Sinaliza com o pisca da direita ao aproximares-te da saída, para avisar quem vem atrás e quem espera para entrar."],
    "2.3": ["Para as saídas que não são a primeira, só se ocupa a via da direita depois de passar a saída imediatamente anterior, com as devidas precauções.", "Art. 14.º-A, n.º 1, al. c)",
      { 1: "Ocupar a via da direita desde a entrada só se faz para a primeira saída. Para a terceira, só passas para a direita depois da saída imediatamente anterior, a segunda.",
        2: "Mudar de via em frente à saída é tardio e perigoso. Passas para a via da direita depois da saída anterior, progressivamente e com as devidas precauções." },
      "A regra conta a partir da tua saída: se saíres na quarta, passas para a via da direita depois da terceira."],
    "2.4": ["Não se sai da rotunda a partir da via interior. Sem espaço para passar à direita, dá-se mais uma volta.", "Art. 14.º-A, n.º 1, al. c)",
      { 1: "Não se sai da rotunda a partir da via interior. Sair à frente do ligeiro corta-lhe a trajetória, mesmo com o pisca ligado.",
        2: "Parar na via interior para esperar surpreende quem vem atrás. Continuas a circular e sais na volta seguinte." },
      "Para não teres de dar mais uma volta, planeia a saída: passa para a via da direita logo a seguir à saída anterior à tua."],
    "2.5": ["Pesados, velocípedes e veículos de tração animal podem circular pela via mais à direita, facilitando a saída dos outros.", "Art. 14.º-A, n.º 2",
      { 1: "Os veículos pesados podem ocupar a via da direita em toda a rotunda. É uma exceção prevista na lei, desde que facilitem a saída a quem circula nas outras vias.",
        2: "A exceção não depende do pisca. O pesado pode circular pela via da direita e sinaliza a saída como qualquer condutor." },
      "A mesma exceção vale para velocípedes, veículos de tração animal e animais. Atrás de um pesado na via da direita, conta que ele pode não sair na saída seguinte."],
    "3.1": ["Quem entra numa autoestrada pelo ramal de acesso cede a passagem a quem nela circula. A regra da direita não se aplica.", "Art. 31.º, n.º 1, al. b)",
      { 1: "A regra da direita não se aplica à entrada na autoestrada. Quem entra pelo ramal de acesso cede a passagem a quem já circula na autoestrada.",
        2: "Parar no fim da via de aceleração obriga a entrar depois quase sem velocidade, o que é perigoso. Ajustas a velocidade e entras no primeiro espaço seguro, atrás do ligeiro." },
      "Antes de entrar, confirma pelo espelho e olhando por cima do ombro: um veículo no ângulo morto não aparece no espelho."],
    "3.2": ["A via de aceleração permite ajustar a velocidade à do trânsito e escolher o momento de entrar, cedendo a passagem. Termina à frente: não serve para circular até à saída seguinte.", "Art. 31.º, n.º 1, al. b)",
      { 1: "A via de aceleração termina pouco depois da entrada. Serve para ajustar a velocidade e entrar na autoestrada, não para circular.",
        2: "Entrar à velocidade do ramal obriga quem circula na autoestrada a travar. A via de aceleração serve para aproximar a tua velocidade da do trânsito antes de entrares." },
      "Na saída é ao contrário: a via de abrandamento serve para reduzir a velocidade já fora da via de trânsito, e não antes de lá chegares."],
    "3.4": ["A prioridade é tua, mas facilitar a entrada evita travagens e situações de risco. Mudar de via de trânsito só se houver espaço e depois de sinalizar.", "Boa prática",
      { 1: "A prioridade é tua, mas acelerar para impedir a entrada cria uma situação de risco. Mantém a velocidade ou facilita a entrada, se for seguro.",
        2: "Uma travagem brusca pode provocar uma colisão com quem vem atrás. Facilitar a entrada faz-se com antecedência, mudando de via ou ajustando a velocidade aos poucos." },
      "Antes de passares para a via do meio, verifica o espelho e o ângulo morto e sinaliza. Se não houver espaço, ficas na tua via: quem entra é que cede a passagem."],
    "3.5": ["Sem marcha de urgência, a ambulância é um veículo como os outros e cede a passagem ao entrar.", "Art. 31.º, n.º 1, al. b)",
      { 1: "A prioridade dos veículos de socorro depende da marcha de urgência, assinalada com luzes e sirene. Sem elas, a ambulância cede a passagem ao entrar, como qualquer veículo.",
        2: "Estar à frente não dá prioridade. Quem entra pelo ramal de acesso cede a passagem a quem circula na autoestrada." },
      "Se a mesma ambulância ligar as luzes e a sirene, passa a estar em marcha de urgência: aí és tu que lhe facilitas a passagem (pergunta 6.2)."],
    "4.1": ["O peão que já iniciou a travessia tem de a poder concluir em segurança. Passar perto ou buzinar põe-no em perigo.", "Art. 11.º, n.º 3; regra da passadeira a confirmar",
      { 1: "O peão que já iniciou a travessia tem de a poder concluir em segurança. Passar atrás dele, mesmo com espaço, põe-no em risco: paras antes da passadeira e esperas.",
        2: "Buzinar não apressa a travessia: assusta o peão e pode provocar uma queda. Paras antes da passadeira e esperas que conclua a travessia." },
      "Ao aproximares-te de uma passadeira, reduz a velocidade e observa os passeios: um peão parado junto à passadeira pode começar a atravessar."],
    "4.3": ["Além de proibido, é perigoso: o carro parado pode estar a deixar passar um peão que tu não vês.", "Art. 41.º, n.º 1, al. d)",
      { 1: "A proibição não depende de veres peões. O veículo parado pode estar a deixar passar um peão que ele te esconde.",
        2: "Buzinar não torna permitida uma ultrapassagem proibida. É proibido ultrapassar imediatamente antes e na passadeira." },
      "No Código, a passadeira é uma «passagem assinalada para a travessia de peões». A mesma proibição vale para as passagens assinaladas para velocípedes."],
    "4.4": ["Parar junto à passadeira tapa a visão de peões e condutores. A lei proíbe parar a menos de 5 m antes dela.", "Art. 49.º, n.º 1, al. d)",
      { 1: "A proibição abrange qualquer paragem, por breve que seja. Deixar sair um passageiro é uma paragem, e a menos de 5 m antes da passadeira não se pode parar.",
        2: "Os quatro piscas assinalam o veículo, mas não tornam permitida uma paragem proibida." },
      "Paragem é a imobilização pelo tempo estritamente necessário para entrar ou sair passageiros ou para breves operações de carga e descarga. Estacionamento é tudo o que vai além disso. Junto à passadeira, ambos são proibidos."],
    "4.5": ["Na ultrapassagem a velocípedes, a lei exige uma distância lateral de pelo menos 1,5 m.", "Art. 18.º, n.º 3",
      { 1: "0,5 m está muito abaixo do mínimo. Ao ultrapassar um velocípede, a distância lateral tem de ser de pelo menos 1,5 m.",
        2: "1 m não chega. A lei exige uma distância lateral de pelo menos 1,5 m entre o teu veículo e o velocípede." },
      "Se não houver espaço para deixar 1,5 m, por exemplo porque vem trânsito em sentido contrário, ficas atrás do ciclista até poderes ultrapassar com essa distância."],
    "5.1": ["A ultrapassagem faz-se pela esquerda.", "Art. 36.º, n.º 1",
      { 1: "A ultrapassagem faz-se pela esquerda. A berma não se destina ao trânsito de veículos, e ultrapassar pela direita surpreende o condutor ultrapassado.",
        2: "O lado da ultrapassagem não depende do espaço: faz-se pela esquerda. Sem espaço à esquerda, não ultrapassas." },
      "Há casos em que se ultrapassa pela direita, como um veículo que sinalizou que vai virar à esquerda e se encostou ao eixo da faixa de rodagem. Fora desses casos, é pela esquerda."],
    "5.2": ["Sem ver o que vem em sentido contrário, não há forma segura de ultrapassar.", "Art. 41.º, n.º 1, al. e)",
      { 1: "A velocidade não compensa a falta de visibilidade. É proibido ultrapassar em curvas de visibilidade reduzida, porque não vês o que vem em sentido contrário.",
        2: "Buzinar não te dá visibilidade nem torna a ultrapassagem permitida. Esperas até teres visibilidade suficiente." },
      "A mesma proibição vale nas lombas e em qualquer local de visibilidade insuficiente. Só inicias uma ultrapassagem se vires espaço livre para a terminar."],
    "5.4": ["Junto a cruzamentos há veículos a entrar e a mudar de direção que não esperam alguém na via de trânsito do sentido contrário.", "Art. 41.º, n.º 1, al. c)",
      { 1: "Ter prioridade no cruzamento não autoriza a ultrapassagem. É proibido ultrapassar imediatamente antes e nos cruzamentos e entroncamentos.",
        2: "O semáforo verde não levanta a proibição. Também nos cruzamentos com semáforos é proibido ultrapassar imediatamente antes e no próprio cruzamento." },
      "A proibição não se aplica se houver duas ou mais vias de trânsito no mesmo sentido e a ultrapassagem não usar a parte da faixa de rodagem destinada ao sentido contrário."],
    "6.1": ["Os veículos em marcha de urgência têm de passar. O condutor facilita-lhes a passagem sem pôr ninguém em perigo.", "A confirmar",
      { 1: "Acelerar aumenta o risco para ti e para a ambulância. Perante um veículo em marcha de urgência, facilitas a passagem, desviando-te quando for seguro.",
        2: "Circular na tua via de trânsito não te dispensa de facilitar a passagem. Perante um veículo em marcha de urgência, todos os condutores lhe abrem caminho." },
      "Desviar-se não é travar de repente: verifica os espelhos, sinaliza e encosta à direita aos poucos. Se não houver espaço, mantém uma marcha previsível até haver."],
    "6.2": ["Em marcha de urgência, a ambulância tem prioridade, mas não pode pôr os outros em perigo. Quem circula na autoestrada facilita a entrada.", "A confirmar",
      { 1: "Em marcha de urgência, a ambulância tem prioridade de passagem. São os condutores que circulam na autoestrada que lhe facilitam a entrada.",
        2: "A prioridade em marcha de urgência não depende de haver trânsito. Quem circula na autoestrada facilita-lhe a entrada sempre que for seguro." },
      "O condutor da ambulância também tem deveres: mesmo em marcha de urgência, não pode pôr em perigo os outros utentes da via."],
    "6.3": ["O verde não te dá prioridade sobre um veículo em marcha de urgência.", "A confirmar",
      { 1: "O sinal verde não te dá prioridade sobre um veículo em marcha de urgência. Paras e deixas passar o veículo dos bombeiros.",
        2: "Avançar depressa pode pôr-te na trajetória do veículo de socorro. Paras e só avanças depois de ele passar." },
      "Antes de retomares a marcha, confirma se não vem outro veículo de socorro atrás do primeiro: muitas vezes circulam em grupo."],
    "6.4": ["Libertar a via de trânsito da esquerda é a forma mais segura de deixar passar o veículo de socorro.", "A confirmar",
      { 1: "Obrigar a ambulância a ultrapassar pela direita é perigoso e imprevisível. Libertas a via de trânsito da esquerda, passando para a direita assim que for seguro.",
        2: "Parar na berma da esquerda, junto ao separador, deixa-te numa posição perigosa e pode bloquear a passagem. Passas para a direita assim que for seguro." },
      "Com duas ou mais vias de trânsito no mesmo sentido, circula-se pela mais à direita; as outras usam-se para ultrapassar ou quando não há lugar naquela. Depois de a ambulância passar, ficas à direita."],
    "7.1": ["A forma diz o tipo de sinal: triângulo com bordo vermelho é perigo, círculo com bordo vermelho é proibição, círculo azul é obrigação.", "RST, art. 20.º, n.º 3, e quadros anexos ao RST",
      { 1: "Os sinais de proibição são redondos, com bordo vermelho. O triângulo com bordo vermelho é um sinal de perigo.",
        2: "Os sinais de obrigação são redondos e azuis. O triângulo com bordo vermelho avisa de um perigo." },
      "Dois sinais fogem à regra da forma, para serem reconhecidos de imediato: o STOP é octogonal e o de cedência de passagem é um triângulo invertido."],
    "7.2": ["Bordo vermelho indica proibição. A velocidade mínima usa um sinal azul.", "RST, art. 24.º (C13)",
      { 1: "A velocidade recomendada usa um sinal quadrado azul. O sinal redondo com bordo vermelho é de proibição.",
        2: "A velocidade mínima obrigatória usa um sinal redondo azul. Bordo vermelho indica proibição: não podes exceder 50 km/h." },
      "50 km/h é também o limite geral dentro das localidades para os ligeiros, mesmo sem sinal."],
    "7.3": ["Sinais redondos azuis são de obrigação: faz-se o que a seta indica.", "RST, art. 27.º (D1)",
      { 1: "A proibição de virar usa um sinal redondo com bordo vermelho e a seta cortada por uma barra. Redondo e azul é obrigação.",
        2: "A cedência de passagem assinala-se com um triângulo invertido. O sinal redondo azul com seta obriga a seguir na direção indicada." },
      "Se a seta estiver inclinada para baixo, o sinal obriga a contornar uma placa ou obstáculo pelo lado indicado."],
    /* Perguntas sem cena desenhada (perguntas_sem_cena.js) */
    "3.3": ["Na autoestrada não se pode circular abaixo de 50 km/h.", "Art. 27.º, n.º 6",
      { 1: "40 km/h fica abaixo do mínimo. Na autoestrada, a velocidade mínima é de 50 km/h.",
        2: "O mínimo é 50 km/h. Circular a 60 km/h é permitido, mas não é esse o limite mínimo." },
      "Na autoestrada há também um limite máximo: 120 km/h para os ligeiros de passageiros, salvo sinalização em contrário."],
    "4.2": ["À aproximação de uma passadeira, o condutor tem de moderar a velocidade. Um peão à espera pode avançar a qualquer momento.", "Art. 25.º, n.º 1, al. a)",
      { 1: "Não é preciso o peão estar na passadeira para teres de moderar a velocidade. A lei manda moderá-la à aproximação das passagens assinaladas para peões.",
        2: "O sinal de luzes não dá ordens a peões e pode ser mal interpretado. Moderas a velocidade e preparas-te para parar, se ele iniciar a travessia." },
      "Se outro veículo parar antes da passadeira, abranda e confirma: pode estar a deixar passar um peão que não vês (pergunta 4.3)."],
    "5.3": ["Numa lomba não se vê quem vem do outro lado.", "Art. 41.º, n.º 1, al. a)",
      { 1: "A lentidão do pesado não levanta a proibição. Numa lomba não vês quem vem em sentido contrário, por isso é proibido ultrapassar.",
        2: "Os máximos não te dão visibilidade para lá da lomba e podem encandear quem vem do outro lado. A proibição de ultrapassar mantém-se." },
      "Tal como nas curvas, a proibição não se aplica se houver duas ou mais vias de trânsito no mesmo sentido e a ultrapassagem não usar a parte da faixa de rodagem destinada ao sentido contrário."],
    "5.5": ["A ultrapassagem só é segura com espaço livre suficiente, os espelhos verificados e a manobra sinalizada.", "A confirmar",
      { 1: "Não basta olhar para o sentido contrário. Também tens de confirmar que tens espaço livre à frente, que ninguém começou a ultrapassar-te e sinalizar a manobra.",
        2: "O sinal de outro condutor não substitui a tua verificação. A responsabilidade pela ultrapassagem é de quem a faz." },
      "Também tens de poder regressar à tua via de trânsito sem prejudicar o veículo ultrapassado. Se não houver espaço para isso, não inicias a ultrapassagem."],
    "6.5": ["Uma travagem brusca pode causar um acidente com quem vem atrás. Primeiro percebe-se de onde vem o veículo e só depois se faz a manobra.", "Boa prática",
      { 1: "Travar a fundo pode provocar uma colisão com quem vem atrás e não ajuda o veículo de socorro. Primeiro localizas de onde ele vem.",
        2: "Os quatro piscas não tornam segura uma travagem brusca e podem confundir os outros condutores. Localizas o veículo, sinalizas e desvias-te com calma." },
      "Usa os espelhos e as janelas para perceber de onde vem a sirene. Se o veículo vier em sentido contrário ou noutra via, pode nem ser preciso desviares-te."],
    "7.4": ["As ordens dos agentes de trânsito prevalecem sobre os sinais e as regras de trânsito.", "Art. 7.º (número a confirmar)",
      { 1: "As ordens dos agentes prevalecem sobre os sinais luminosos. Se o agente te manda avançar, avanças, mesmo com o vermelho.",
        2: "O sinal sonoro não serve para confirmar uma ordem e pode perturbar o agente. A ordem é clara: avanças." },
      "A ordem completa: primeiro os agentes; depois os sinais (temporários, de mensagem variável, luminosos, verticais e marcas, por esta ordem); por fim, as regras gerais de trânsito."],
    "7.5": ["O amarelo manda parar. Só se avança quando parar já não é possível com segurança.", "A confirmar",
      { 1: "O amarelo não é um aviso para acelerar: manda parar. Acelerar para passar aumenta o risco de entrares no cruzamento já com vermelho.",
        2: "O amarelo manda parar, mas não a qualquer custo. Se já não consegues parar em segurança, por exemplo sem travar bruscamente, avanças." },
      "O amarelo fixo vem depois do verde e antes do vermelho. O amarelo intermitente é diferente: não manda parar, obriga a abrandar e a ter especial cuidado."],
    "8.1": ["Com o piso molhado, precisas de mais espaço para travar. A distância tem de ser suficiente para evitar acidentes se o da frente travar.", "Art. 18.º, n.º 1",
      { 1: "Com o piso molhado, a distância de travagem aumenta. A distância que bastava com piso seco deixa de ser suficiente.",
        2: "Aproximar-te reduz o espaço para travar, precisamente quando precisas de mais. A distância tem de aumentar, não diminuir." },
      "Na regra dos 2 segundos, com piso molhado conta pelo menos o dobro: 4 segundos (pergunta 8.2)."],
    "8.3": ["Os máximos refletem no nevoeiro e encandeiam. Com visibilidade muito reduzida, abranda-se e usam-se as luzes de nevoeiro, desligando-as quando a visibilidade melhorar.", "A confirmar",
      { 1: "Os máximos refletem no nevoeiro e reduzem ainda mais a visibilidade. Usas as luzes de nevoeiro e reduzes a velocidade.",
        2: "Seguir colado não deixa espaço para travar se o da frente parar. Reduzes a velocidade e manténs uma distância que te permita parar no espaço que vês." },
      "As luzes de nevoeiro só se usam com visibilidade muito reduzida. Quando a visibilidade melhorar, desligam-se, sobretudo a de trás, que encandeia quem vem atrás."],
    "8.4": ["Os máximos encandeiam quem vem em sentido contrário. Passa-se para os médios ao cruzar com outros veículos.", "A confirmar",
      { 1: "Manter os máximos encandeia o condutor que vem em sentido contrário. Ao cruzar com outros veículos, passas para os médios.",
        2: "Desligar as luzes, mesmo por instantes, deixa-te sem ver e sem seres visto. Passas para os médios." },
      "O mesmo vale quando segues atrás de outro veículo: os máximos encandeiam-no pelos espelhos. Também aí usas os médios."],
    "8.5": ["Uma travagem brusca ou um golpe de volante sem aderência fazem o carro despistar-se. Deixa-se o carro abrandar até os pneus voltarem a agarrar.", "Boa prática",
      { 1: "Sem aderência, uma travagem a fundo não faz o carro parar e pode fazê-lo despistar-se. Tiras o pé do acelerador e deixas o carro abrandar.",
        2: "Um golpe de volante sem aderência não muda a trajetória e, quando os pneus voltarem a agarrar, o carro pode sair na direção para onde as rodas apontam." },
      "Para evitar a aquaplanagem, reduz a velocidade com chuva forte e verifica a pressão e o piso dos pneus."],
    /* Lote 1: O condutor (unidade II) */
    "9.1": ["Considera-se sob a influência de álcool o condutor com taxa igual ou superior a 0,5 g/l. Para quem está em regime probatório ou é condutor profissional, o limite é 0,2 g/l.", "Art. 81.º",
      { 1: "0,8 g/l é o limite a partir do qual a infração passa a muito grave. A proibição começa antes, nos 0,5 g/l.",
        2: "1,2 g/l é o limite a partir do qual conduzir passa a ser crime. A proibição começa muito antes, nos 0,5 g/l." },
      "O teste no ar expirado mede miligramas por litro; a lei converte-os: 1 mg/l de ar expirado equivale a 2,3 g/l de sangue."],
    "9.2": ["Nos primeiros 3 anos de carta (regime probatório), o limite é 0,2 g/l, mais baixo do que o geral. O mesmo limite vale para condutores profissionais, como os de táxi, de pesados ou de veículos de socorro.", "Art. 81.º",
      { 1: "0,5 g/l é o limite geral. Em regime probatório, o limite é mais baixo: 0,2 g/l.",
        2: "0,8 g/l está muito acima do limite. Em regime probatório, a proibição começa nos 0,2 g/l." },
      "0,2 g/l atinge-se com muito pouco álcool. Em regime probatório, a forma segura é não beber nada antes de conduzir."],
    "9.3": ["Com taxa igual ou superior a 1,2 g/l, a condução é crime, punido com prisão até 1 ano ou multa, além da proibição de conduzir. A partir de 0,5 g/l e abaixo de 1,2 g/l, é contraordenação grave ou muito grave.", "Código Penal, art. 292.º",
      { 1: "Entre 0,8 e 1,2 g/l é contraordenação muito grave, não crime. O crime começa nos 1,2 g/l.",
        2: "Entre 0,5 e 0,8 g/l é contraordenação grave, não crime. O crime começa nos 1,2 g/l." },
      "Na carta por pontos, a contraordenação grave tira 3 pontos, a muito grave tira 5 e o crime tira 6."],
    "9.4": ["O organismo elimina o álcool a um ritmo que não se consegue acelerar. Café, duche ou comida não baixam a taxa: no máximo, disfarçam o cansaço.", "Boa prática",
      { 1: "O café pode fazer-te sentir mais desperto, mas não baixa a taxa de álcool nem torna as reações mais rápidas.",
        2: "O duche frio não acelera a eliminação do álcool. A taxa só desce com o tempo." },
      "Se beberes muito à noite, podes ainda estar acima do limite na manhã seguinte. Conta com isso antes de conduzir."],
    "9.5": ["Mesmo em pequenas quantidades, o álcool aumenta o tempo de reação, reduz o campo visual e dá uma falsa confiança. O limite legal não é um limite seguro.", "Boa prática",
      { 1: "O álcool não melhora a concentração. Pode dar uma sensação de descontração, mas torna as reações mais lentas.",
        2: "O efeito começa antes do limite legal: abaixo dele, já há reações mais lentas e mais confiança do que devia." },
      "A forma mais segura é combinar antes de sair quem conduz e não bebe, ou outro meio de transporte."],
    "9.6": ["O condutor é obrigado a fazer os testes de deteção de álcool e de substâncias psicotrópicas. Recusar é crime de desobediência.", "Art. 152.º (número a confirmar)",
      { 1: "O teste pode ser pedido em qualquer fiscalização, haja ou não acidente. Recusar é crime.",
        2: "A recusa não é uma simples coima: é crime de desobediência." },
      "Se não concordares com o resultado do primeiro teste, podes pedir uma contraprova, mas não podes recusar o teste."],
    "9.7": ["É proibido conduzir sob a influência de substâncias psicotrópicas, e pode ser crime, tal como o álcool a partir de 1,2 g/l.", "Art. 81.º; Código Penal, art. 292.º",
      { 1: "Não há quantidade permitida: conduzir sob a influência de drogas é proibido.",
        2: "A proibição das drogas não depende do álcool. Juntar os dois agrava ainda mais os efeitos." },
      "Os efeitos de algumas drogas duram muitas horas depois do consumo, mesmo quando a pessoa já se sente bem."],
    "9.8": ["Alguns medicamentos reduzem a atenção e os reflexos. O folheto informativo diz se afetam a capacidade de conduzir; em caso de dúvida, pergunta ao médico ou ao farmacêutico.", "Boa prática",
      { 1: "Ser receitado não quer dizer que seja seguro conduzir. Lê o folheto ou pergunta ao médico.",
        2: "O café não anula o efeito do medicamento. Se o folheto avisar, não conduzes." },
      "Antialérgicos, calmantes, relaxantes musculares e alguns xaropes para a tosse são exemplos de medicamentos que podem dar sonolência."],
    "9.9": ["O álcool e muitos medicamentos reforçam-se: juntos, a sonolência e a lentidão das reações são maiores do que com cada um sozinho.", "Boa prática",
      { 1: "O álcool não anula o medicamento. Pelo contrário, pode aumentar os efeitos dele.",
        2: "Mesmo abaixo do limite legal, o álcool somado ao medicamento pode tornar a condução perigosa." },
      "O folheto do medicamento costuma dizer se não se deve beber álcool durante o tratamento. Lê-o antes de conduzir."],
    "9.10": ["Bocejos repetidos, olhos pesados, falhas de atenção e dificuldade em manter a trajetória são sinais de fadiga. Quando aparecem, é preciso parar.", "Boa prática",
      { 1: "Querer ouvir música não indica cansaço. Os sinais são bocejos, olhos pesados e dificuldade em manter a trajetória.",
        2: "A fome não é um sinal de fadiga. Os sinais são bocejos, olhos pesados e dificuldade em manter a trajetória." },
      "Se não te lembras dos últimos quilómetros que fizeste, a atenção já falhou: para logo que possas."],
    "9.11": ["Recomenda-se uma pausa de cerca de 15 minutos a cada 2 horas de condução, ou antes, se sentires cansaço.", "Boa prática",
      { 1: "Conduzir horas seguidas sem parar aumenta o cansaço e o risco. Recomenda-se uma pausa a cada 2 horas.",
        2: "5 horas seguidas é demasiado. Recomenda-se uma pausa a cada 2 horas, ou antes, se te sentires cansado." },
      "Na pausa, sai do carro, caminha um pouco e bebe água. Se tiveres sono, uma sesta curta ajuda mais do que um café."],
    "9.12": ["O sono só passa a dormir. Abrir a janela ou aumentar o volume dá uma sensação passageira de alerta, mas não evita adormecer.", "Boa prática",
      { 1: "Janela aberta e rádio alto só dão alerta por alguns minutos. Com sono, a solução é parar e descansar.",
        2: "Acelerar com sono aumenta o risco: tens menos tempo para reagir e o cansaço não passa." },
      "Na autoestrada, usa as áreas de serviço para parar. A berma é só para emergências."],
    "9.13": ["O relógio biológico faz baixar a atenção sobretudo de madrugada (por volta das 2h às 6h) e no início da tarde, depois do almoço.", "Boa prática",
      { 1: "A meio da manhã a atenção costuma estar alta. Os períodos de maior risco são a madrugada e o início da tarde.",
        2: "O fim da tarde não é o período de maior risco. Os mais perigosos são a madrugada e o início da tarde." },
      "Se tiveres de conduzir de madrugada ou depois de uma refeição pesada, dorme bem antes e planeia mais pausas."],
    "9.14": ["O código 01 na carta obriga a conduzir com a correção da visão. Sem ela, estás a conduzir sem cumprir as restrições do teu título de condução.", "A confirmar",
      { 1: "A restrição vale sempre, mesmo que te pareça que vês bem. O código 01 obriga a usar óculos ou lentes.",
        2: "A obrigação não depende da hora. Com o código 01, conduzes sempre com óculos ou lentes." },
      "Se a tua visão mudar, faz uma nova avaliação: a correção que usas tem de ser a adequada, não uns óculos antigos."],
    "9.15": ["Quanto maior a velocidade, mais o olhar se fixa ao longe e menos se repara no que está dos lados. É o chamado efeito de túnel.", "Boa prática",
      { 1: "Com mais velocidade, o campo de visão útil estreita-se, não alarga: vês menos o que acontece dos lados.",
        2: "A velocidade muda o que consegues ver: quanto mais depressa, mais estreito o campo de visão útil." },
      "É por isso que, perto de escolas e passadeiras, moderar a velocidade te ajuda a ver os peões que surgem dos lados."],
    "9.16": ["Alterações da visão ou outras condições de saúde podem afetar a aptidão para conduzir. Quem nota uma alteração deve fazer uma avaliação médica.", "A confirmar",
      { 1: "Ver bem de dia não chega: à noite também precisas de ver bem para conduzir com segurança. Faz uma avaliação médica.",
        2: "Os máximos encandeiam os outros condutores e não corrigem a tua visão. O caminho é a avaliação médica." },
      "Com a idade, a visão noturna e a recuperação do encandeamento pioram. Os exames médicos para revalidar a carta servem também para detetar isto."],
    "9.17": ["A raiva e o stress reduzem a atenção e levam a decisões arriscadas. Antes de conduzir, espera até estares calmo.", "Boa prática",
      { 1: "Descarregar a tensão na condução leva a velocidade excessiva e a manobras arriscadas. Espera até te acalmares.",
        2: "A raiva não te deixa mais alerta: estreita a atenção e aumenta a agressividade. Espera até estares calmo." },
      "O mesmo vale para a tristeza ou preocupações fortes: se a cabeça está noutro sítio, a atenção na estrada falha."],
    "9.18": ["É proibido usar, durante a marcha, aparelhos que possam prejudicar a condução, como o telemóvel na mão. A exceção são os aparelhos com um só auricular ou com alta voz, sem manuseamento continuado.", "Art. 84.º, n.º 1 e 2",
      { 1: "A velocidade não muda a proibição: ler no telemóvel tira-te os olhos e a atenção da estrada.",
        2: "A proibição vale em qualquer via, com ou sem trânsito: os olhos saem da estrada na mesma." },
      "Parado num semáforo ou numa fila, continuas a conduzir, e a proibição mantém-se. Se precisares mesmo, para o carro num local onde seja permitido."],
    "9.19": ["A lei só permite aparelhos com um auricular ou com microfone de alta voz, desde que não obriguem a manusear o telemóvel de forma continuada.", "Art. 84.º, n.º 2",
      { 1: "Ter o telemóvel na mão é proibido, mesmo em chamadas curtas.",
        2: "Auscultadores nos dois ouvidos não são permitidos: impedem-te de ouvir o que se passa à tua volta." },
      "Mesmo em alta voz, uma conversa difícil tira atenção à estrada. Se a chamada exigir concentração, para num local seguro."],
    "9.20": ["Programar o GPS obriga a manusear o aparelho e a tirar os olhos da estrada. Faz-se antes de arrancar, com o veículo parado.", "Art. 84.º, n.º 1",
      { 1: "Mesmo numa reta, mexer no GPS tira-te os olhos e as mãos da condução.",
        2: "Parado num semáforo continuas a conduzir, e o sinal pode mudar a qualquer momento. Programa o GPS antes de arrancar." },
      "Durante a viagem, usa as indicações de voz e, se precisares de mudar o destino, para num local seguro."],
    "10.1": ["Os sinais de regulamentação dividem-se em quatro tipos: cedência de passagem, proibição, obrigação e prescrição específica. Os sinais de perigo são uma classe à parte: avisam de condições perigosas, não impõem uma regra.", "RST, art. 6.º e 8.º",
      { 1: "Os sinais de cedência de passagem, como o STOP, são sinais de regulamentação: impõem a obrigação de ceder a passagem.",
        2: "Os sinais de proibição são sinais de regulamentação: proíbem uma manobra ou o trânsito de certos veículos." },
      "Alguns sinais de cedência de passagem são triangulares, como o de aproximação de rotunda (B7). Parecem sinais de perigo, mas pertencem à regulamentação."],
    "10.2": ["Os sinais de perigo colocam-se, em regra, a não menos de 150 m nem a mais de 300 m do ponto a que se referem. Se o local não o permitir, um painel adicional indica a distância.", "RST, art. 20.º, n.º 1",
      { 1: "O sinal de perigo fica antes do perigo, para dar tempo de abrandar. Em regra, o perigo está entre 150 e 300 m depois do sinal.",
        2: "A distância máxima, em regra, é de 300 m. Quando é diferente, um painel adicional por baixo do sinal indica a distância." },
      "Este sinal (A1a) anuncia uma curva perigosa à direita. Ao vê-lo, moderas a velocidade antes de chegares à curva, não dentro dela."],
    "10.3": ["O sinal A24 anuncia um cruzamento ou entroncamento onde vigora a regra geral da prioridade à direita.", "RST, art. 19.º (A24)",
      { 1: "Este sinal não te dá prioridade. O cruzamento onde tens prioridade é anunciado por outro sinal (B8), com uma linha mais grossa na tua via.",
        2: "Este sinal não proíbe manobras: é um sinal de perigo. As proibições de virar usam sinais redondos com orla vermelha." },
      "Este sinal só excecionalmente se usa dentro das localidades. Ao vê-lo, abrandas e preparas-te para ceder a passagem a quem se apresente pela tua direita."],
    "10.4": ["O sinal B8 anuncia um cruzamento com uma via sem prioridade: os condutores dessa via é que cedem a passagem. A linha grossa representa a tua via.", "RST, art. 21.º (B8)",
      { 1: "A prioridade à direita é o que vale com o sinal A24, que tem uma cruz com linhas iguais. Aqui, a linha grossa mostra que a tua via tem prioridade.",
        2: "O fim da via com prioridade usa o sinal B4, o losango amarelo com riscas. Este sinal anuncia um cruzamento onde tens prioridade." },
      "Ter prioridade não dispensa a atenção: antes de entrares no cruzamento, confirma que os outros condutores estão mesmo a ceder."],
    "10.5": ["O sinal A16a é um sinal de perigo: anuncia a aproximação de uma passagem de peões. No local da passagem, o sinal é quadrado e azul (H7).", "RST, art. 19.º (A16a)",
      { 1: "O sinal triangular fica antes da passagem, para avisar. No local da passagem, o sinal é quadrado e azul (H7).",
        2: "Este é um sinal de perigo, não de proibição. A proibição de trânsito de peões usa um sinal redondo com orla vermelha (C3l)." },
      "Ao ver este sinal, moderas a velocidade e procuras peões junto aos passeios, sobretudo entre carros estacionados."],
    "10.6": ["O sinal B3 indica que os condutores da via onde está colocado têm prioridade de passagem na próxima intersecção. Quem vem das outras vias cede a passagem.", "RST, art. 21.º (B3)",
      { 1: "A prioridade à direita só vale quando não há sinais. Com este sinal, a tua via tem prioridade.",
        2: "A ordem de chegada nunca dá prioridade. Com este sinal, és tu quem passa primeiro." },
      "As outras vias costumam ter sinais de cedência de passagem ou STOP. Mesmo assim, confirma que os outros condutores estão a parar."],
    "10.7": ["O sinal B4 indica que, a partir dali, a via deixa de ter prioridade. Nos cruzamentos seguintes valem os sinais que lá houver ou, se não houver nenhum, a prioridade à direita.", "RST, art. 21.º (B4)",
      { 1: "O fim da prioridade não obriga a parar. Só tens de parar onde houver STOP ou quando for preciso para ceder a passagem.",
        2: "As riscas sobre o losango indicam o fim. O início de uma via com prioridade usa o losango amarelo sem riscas (B3)." },
      "Depois deste sinal, abranda antes do próximo cruzamento: podes ter de ceder a passagem a quem se apresente pela tua direita."],
    "10.8": ["Com o sinal STOP, o condutor é obrigado a parar antes de entrar no cruzamento ou entroncamento, mesmo sem trânsito. Depois, cede a passagem a quem circula na outra via.", "RST, art. 21.º (B2)",
      { 1: "Com STOP, abrandar não chega: a paragem é obrigatória, mesmo que a via esteja livre.",
        2: "A paragem não depende do trânsito: com STOP, paras sempre." },
      "Paras na linha de paragem. Se dali não vires a outra via, avanças devagar, já depois de teres parado, até teres visibilidade."],
    "10.9": ["O sinal de cedência de passagem obriga a ceder a passagem a todos os veículos que circulam na via de que te aproximas. Não obriga a parar: só paras se for preciso para ceder.", "RST, art. 21.º (B1)",
      { 1: "A paragem obrigatória é só do STOP. Com cedência de passagem, abrandas e paras apenas se for necessário.",
        2: "A linha de cedência (os triângulos no chão) marca onde paras, se tiveres de parar. Com a via livre, não te obriga a parar." },
      "Abranda o suficiente para olhares bem para os dois lados. Se tiveres dúvidas sobre a velocidade de quem vem, cede."],
    "10.10": ["O sinal B7 anuncia a proximidade de uma rotunda, uma praça onde o trânsito circula em sentido giratório. Pertence aos sinais de cedência de passagem.", "RST, art. 21.º (B7)",
      { 1: "As setas em círculo representam a rotunda, não uma inversão de marcha. Este sinal só anuncia que a rotunda está próxima.",
        2: "Quem entra numa rotunda não tem prioridade: cede a passagem a quem já circula nela." },
      "À entrada da rotunda costuma haver um sinal redondo azul com setas (D4) e um sinal de cedência de passagem."],
    "10.11": ["O sinal C1 (sentido proibido) proíbe transitar no sentido para o qual está orientado. A rua pode ter trânsito no outro sentido.", "RST, art. 24.º (C1)",
      { 1: "A proibição nos dois sentidos é dada pelo sinal C2, redondo e branco com orla vermelha. O C1 só proíbe o sentido para onde está virado.",
        2: "O estacionamento proibido usa um sinal azul com orla e barra vermelhas (C15). Este sinal proíbe a entrada." },
      "É o sinal que vês no fim de uma rua de sentido único, virado para quem quisesse entrar ao contrário. Na outra ponta, costuma estar o sinal de trânsito de sentido único (H3)."],
    "10.12": ["O sinal C2 (trânsito proibido) proíbe transitar em ambos os sentidos.", "RST, art. 24.º (C2)",
      { 1: "Proibir só um sentido é o sinal C1, vermelho com uma barra branca. O C2 proíbe os dois sentidos.",
        2: "A proibição de parar e estacionar usa um sinal azul com uma cruz vermelha (C16)." },
      "Um painel adicional por baixo do sinal pode limitar a proibição, por exemplo a certas horas ou deixando passar certos veículos."],
    "10.13": ["O sinal C14a proíbe ultrapassar outros veículos que não sejam velocípedes, ciclomotores de duas rodas e motociclos sem carro lateral. Ultrapassar um ciclista continua permitido, se for seguro.", "RST, art. 24.º (C14a)",
      { 1: "O sinal tem exceções: velocípedes, ciclomotores de duas rodas e motociclos sem carro lateral podem ser ultrapassados.",
        2: "Quem decide se a ultrapassagem é segura és tu, não o ciclista. Um sinal dele não te dispensa de confirmar." },
      "Ao ultrapassar um ciclista, abranda e deixa pelo menos 1,5 m de distância lateral. Se houver linha contínua, não a podes pisar nem transpor: esperas por um local onde a ultrapassagem seja permitida."],
    "10.14": ["O sinal C15 proíbe estacionar. A paragem, pelo tempo estritamente necessário para a entrada ou saída de passageiros, continua permitida.", "RST, art. 24.º (C15); Código da Estrada, art. 48.º",
      { 1: "Proibir parar e estacionar é o sinal C16, com uma cruz vermelha. Este sinal tem só uma barra: proíbe apenas estacionar.",
        2: "Não há tolerância de minutos: qualquer imobilização que não seja paragem é estacionamento, e aqui é proibida." },
      "Paragem é imobilizar o veículo só o tempo necessário para entrarem ou saírem passageiros ou para breves cargas e descargas, com o condutor pronto a seguir. Se sais e deixas o carro, já é estacionamento."],
    "10.15": ["O sinal C16 proíbe parar ou estacionar quaisquer veículos. Nem a paragem para entrar ou sair passageiros é permitida.", "RST, art. 24.º (C16)",
      { 1: "Proibir só o estacionamento é o sinal C15, com uma barra. A cruz proíbe também a paragem.",
        2: "A proibição de trânsito usa um sinal branco com orla vermelha (C2). Este sinal só trata de parar e estacionar." },
      "Mesmo uma paragem curta, sem saíres do carro, é proibida. O fim da proibição é indicado pelo sinal C21."],
    "10.16": ["O sinal C20a indica o local a partir do qual cessam todas as proibições impostas antes, por sinalização, aos condutores de veículos em marcha, como um limite de velocidade ou a proibição de ultrapassar.", "RST, art. 24.º (C20a)",
      { 1: "O fim de localidade tem um sinal próprio, de indicação. Este sinal só põe fim a proibições.",
        2: "As proibições de parar e estacionar não acabam com este sinal: o fim delas é indicado pelo sinal C21." },
      "Os limites gerais do Código continuam a valer: dentro de uma localidade, o limite de 50 km/h mantém-se depois deste sinal."],
    "10.17": ["O sinal C11b proíbe virar à esquerda na próxima intersecção. Depois dela, a proibição deixa de valer.", "RST, art. 24.º (C11b)",
      { 1: "A proibição não acompanha a via até ao fim da localidade: aplica-se só à intersecção seguinte.",
        2: "Este sinal não precisa de um sinal de fim: vale só para a próxima intersecção." },
      "Este sinal pode estar a alguma distância da intersecção, para teres tempo de escolher a via de trânsito certa."],
    "10.18": ["O sinal D4 indica a entrada numa rotunda, onde vigoram as regras próprias destas intersecções e o trânsito se faz em sentido giratório.", "RST, art. 27.º (D4)",
      { 1: "As setas mostram o sentido de circulação na rotunda, não uma inversão de marcha.",
        2: "A aproximação de uma rotunda é anunciada pelo sinal triangular B7. O sinal redondo azul está à entrada da própria rotunda." },
      "Na rotunda circulas no sentido contrário ao dos ponteiros do relógio e, ao entrar, cedes a passagem a quem já circula nela."],
    "10.19": ["O sinal D8 obriga a transitar a uma velocidade não inferior à indicada. A cor azul indica obrigação.", "RST, art. 27.º (D8)",
      { 1: "A velocidade máxima usa um sinal redondo branco com orla vermelha (C13). O azul indica uma velocidade mínima.",
        2: "A velocidade recomendada usa um sinal quadrado azul (H6). Este sinal é uma obrigação." },
      "Circular muito devagar também cria perigo, porque obriga os outros a travar ou a ultrapassar. O fim desta obrigação é indicado pelo sinal D14."],
    "10.20": ["O sinal D3 obriga a contornar a placa ou o obstáculo pelo lado indicado pela seta. Aqui, a seta aponta para baixo e para a direita: passas pela direita.", "RST, art. 27.º (D3)",
      { 1: "A obrigação de seguir num sentido usa uma seta direita ou curva (D1). A seta inclinada indica o lado por onde contornas o obstáculo.",
        2: "A via sem saída tem um sinal quadrado de indicação (H4). Este sinal é de obrigação." },
      "Encontras este sinal em ilhéus e separadores. Contorná-los pelo lado errado leva-te para o sentido contrário."],
    "11.1": ["Dentro das localidades, o limite geral para automóveis ligeiros e motociclos é de 50 km/h. Um sinal pode fixar outro limite numa via concreta.", "Código da Estrada, art. 27.º, n.º 1",
      { 1: "40 km/h não é um limite geral. Dentro das localidades, sem sinal, o limite é de 50 km/h.",
        2: "60 km/h excede o limite geral. Dentro das localidades, sem sinal, o máximo é de 50 km/h." },
      "O limite é um máximo, não um objetivo: numa rua estreita, com carros estacionados e peões, a velocidade adequada pode ser bem mais baixa."],
    "11.2": ["Fora das localidades, o limite geral dos automóveis ligeiros sem reboque é de 90 km/h. Nas vias reservadas a automóveis e motociclos é de 100 km/h e nas autoestradas de 120 km/h.", "Código da Estrada, art. 27.º, n.º 1",
      { 1: "100 km/h é o limite das vias reservadas a automóveis e motociclos, não das estradas comuns fora das localidades.",
        2: "80 km/h fica abaixo do limite geral. Fora das localidades, o máximo para um ligeiro sem reboque é de 90 km/h." },
      "As vias reservadas a automóveis e motociclos estão sinalizadas à entrada. Sem esse sinal nem outro limite, numa estrada fora das localidades vale o limite de 90 km/h."],
    "11.3": ["Com reboque, os limites gerais dos ligeiros baixam: 50 km/h dentro das localidades, 70 km/h fora delas, 80 km/h nas vias reservadas a automóveis e motociclos e 100 km/h nas autoestradas.", "Código da Estrada, art. 27.º, n.º 1",
      { 1: "120 km/h é o limite de um ligeiro sem reboque. Com reboque, o máximo na autoestrada é de 100 km/h.",
        2: "80 km/h é o limite com reboque nas vias reservadas a automóveis e motociclos. Na autoestrada é de 100 km/h." },
      "O reboque aumenta a distância de travagem e torna o conjunto mais sensível ao vento e às curvas. Mantém mais distância para o veículo da frente."],
    "11.4": ["O condutor deve regular a velocidade tendo em conta a via, o tempo, a visibilidade e o trânsito, de modo a poder parar no espaço livre e visível à sua frente. O limite é um máximo, não a velocidade a que se deve andar.", "Código da Estrada, art. 24.º, n.º 1",
      { 1: "O limite é o máximo permitido em boas condições. À noite, com chuva e curvas, a velocidade segura é mais baixa.",
        2: "Não há uma regra fixa de 10 km/h abaixo do limite. A velocidade certa é a que te deixa parar no espaço que vês livre à frente." },
      "Se só vês a estrada livre até à próxima curva, tens de conseguir parar antes dela, mesmo que isso obrigue a circular bem abaixo do limite."],
    "11.5": ["A lei manda moderar especialmente a velocidade em vários locais, entre eles à aproximação de escolas, hospitais e creches sinalizados, de passadeiras, de curvas, de cruzamentos e de locais com pouca visibilidade.", "Código da Estrada, art. 25.º, n.º 1",
      { 1: "Numa reta livre e com boa visibilidade não há obrigação especial de moderar, desde que respeites o limite e as condições da via.",
        2: "Na via de aceleração ganhas velocidade para entrar com segurança no trânsito da autoestrada, cedendo sempre a passagem." },
      "A lista inclui também as descidas acentuadas, as pontes e os túneis, o piso molhado ou em mau estado e os locais com sinais de perigo."],
    "11.6": ["Os condutores não devem transitar em marcha cuja lentidão cause embaraço injustificado aos outros utentes da via. Circular devagar só é correto quando há motivo, como o trânsito, o tempo ou o estado da via.", "Código da Estrada, art. 26.º",
      { 1: "A lei também proíbe a lentidão injustificada que embarace os outros. Na autoestrada há, além disso, uma velocidade mínima de 50 km/h.",
        2: "A proibição da lentidão injustificada vale em todas as vias, não só na autoestrada." },
      "Se tiveres mesmo de seguir devagar, mantém-te o mais à direita possível e facilita a ultrapassagem a quem vem atrás."],
    "11.7": ["A posição de marcha faz-se pelo lado direito da faixa de rodagem, conservando das bermas ou passeios uma distância suficiente para evitar acidentes. O lado esquerdo só se usa para ultrapassar ou mudar de direção.", "Código da Estrada, art. 13.º, n.º 1 e 2",
      { 1: "Mesmo sem trânsito, o centro da faixa invade o lado de quem vem em sentido contrário, por exemplo à saída de uma curva.",
        2: "Encostado à berma, ficas sem margem para peões, ciclistas ou obstáculos. A lei pede uma distância suficiente da berma." },
      "À saída de uma curva ou de uma lomba, um carro que surja em sentido contrário pode vir perto do eixo. Manter-te à direita dá margem aos dois."],
    "11.8": ["Quando há duas ou mais vias de trânsito no mesmo sentido, o trânsito faz-se pela via mais à direita. As outras só se usam se não houver lugar nela, para ultrapassar ou para mudar de direção.", "Código da Estrada, art. 13.º, n.º 3",
      { 1: "Com a via da direita livre, não há razão para ficar no meio. A regra é circular pela via mais à direita.",
        2: "A via não se escolhe pela velocidade. Com a via da direita livre, é nela que circulas." },
      "Ficar na via do meio sem motivo obriga quem vem atrás a ultrapassar-te pela esquerda e torna o trânsito menos previsível."],
    "11.9": ["Dentro das localidades, os condutores devem usar a via de trânsito mais conveniente ao seu destino. Só podem mudar de via, com as devidas precauções, para mudar de direção, ultrapassar, parar ou estacionar.", "Código da Estrada, art. 14.º, n.º 2",
      { 1: "Dentro das localidades, a regra é usar a via mais conveniente ao destino. Para virar à esquerda, é a via da esquerda.",
        2: "Mudar de via dentro do cruzamento é perigoso: escolhe a via antes, com antecedência." },
      "As setas pintadas no pavimento costumam indicar para onde segue cada via. Escolhe a via cedo e muda com o pisca e com segurança."],
    "11.10": ["Quando o trânsito intenso ocupa todas as vias de um sentido e cada veículo depende da marcha dos que o precedem, os condutores não podem sair da sua fila para outra mais à direita, salvo para mudar de direção, parar ou estacionar.", "Código da Estrada, art. 15.º, n.º 1",
      { 1: "O pisca não torna a manobra permitida. Em filas paralelas, só passas para a direita para mudar de direção, parar ou estacionar.",
        2: "A regra da via mais à direita não se aplica às filas paralelas: aí, passar para a fila da direita para ganhar lugares é proibido." },
      "Trocar de fila no trânsito parado quase não faz ganhar tempo e aumenta muito o risco de toques laterais."],
    "11.11": ["Para mudar de direção para a direita, o condutor deve aproximar-se, com a necessária antecedência e quanto possível, do limite direito da faixa de rodagem e fazer a manobra no trajeto mais curto.", "Código da Estrada, art. 43.º, n.º 1",
      { 1: "Abrir para a esquerda antes de virar confunde quem vem atrás e deixa espaço para alguém passar pela tua direita, como um ciclista.",
        2: "Virar a partir do centro, à última hora, obriga a uma curva larga e surpreende quem vem atrás." },
      "Antes de virar, confirma o espelho e o ângulo morto do lado direito: ciclistas e motociclos podem vir junto ao passeio."],
    "11.12": ["Para mudar de direção para a esquerda, o condutor aproxima-se do eixo da faixa de rodagem, se a via tiver trânsito nos dois sentidos, ou do limite esquerdo, se for de sentido único. Depois entra na outra via pelo lado destinado ao seu sentido.", "Código da Estrada, art. 44.º, n.º 1",
      { 1: "Ficar junto à direita para virar à esquerda obriga a atravessar toda a faixa no cruzamento e confunde quem vem atrás.",
        2: "Passar para o lado esquerdo antes do cruzamento é circular em sentido contrário. Ficas junto ao eixo, mas do teu lado." },
      "Se a via for de sentido único, aproximas-te do limite esquerdo da faixa de rodagem."],
    "11.13": ["Quando as duas vias têm trânsito nos dois sentidos, a mudança de direção para a esquerda faz-se de modo a dar a esquerda ao centro da intersecção, ou seja, a deixá-lo à tua esquerda.", "Código da Estrada, art. 44.º, n.º 2",
      { 1: "Cortar por dentro leva-te a invadir o lado de quem vai entrar no cruzamento vindo da via para onde viras.",
        2: "O pisca é obrigatório, mas não decide o trajeto: a lei manda deixar o centro do cruzamento à tua esquerda." },
      "Na prática, avanças até ao centro do cruzamento, contorna-lo pela direita e entras na nova via do lado do teu sentido."],
    "11.14": ["Antes de mudar de via de trânsito, o condutor assinala a intenção com a necessária antecedência e só faz a manobra em local e por forma que não cause perigo ou embaraço ao trânsito.", "Código da Estrada, art. 21.º, n.º 1, e art. 35.º, n.º 1",
      { 1: "O pisca avisa, mas não dá prioridade: só mudas de via se não causares perigo ou embaraço a ninguém.",
        2: "O sinal faz-se com antecedência, antes da manobra, para os outros perceberem o que vais fazer." },
      "Um veículo no ângulo morto pode não aparecer nos espelhos. Olhar por cima do ombro antes de mudar de via evita o toque lateral."],
    "11.15": ["É proibido inverter o sentido de marcha nas lombas, nas curvas, cruzamentos ou entroncamentos de visibilidade reduzida, nas pontes, passagens de nível e túneis, onde a visibilidade seja insuficiente e quando houver grande intensidade de trânsito.", "Código da Estrada, art. 45.º, n.º 1",
      { 1: "A rapidez não resolve: quem vem do outro lado da curva não te vê a tempo de travar.",
        2: "Os quatro piscas não tornam a manobra permitida nem dão tempo a quem surge da curva para parar." },
      "Segue até um local com boa visibilidade e espaço, ou até uma rotunda, e volta para trás aí."],
    "11.16": ["A lei proíbe inverter o sentido de marcha nas pontes, passagens de nível e túneis, entre outros locais onde a manobra é perigosa.", "Código da Estrada, art. 45.º, n.º 1, alínea c)",
      { 1: "Numa reta larga, com boa visibilidade e sem trânsito, a inversão é permitida, se não houver sinal a proibi-la e se a fizeres sem perigo.",
        2: "Dar a volta completa a uma rotunda é uma forma segura e permitida de voltar para trás." },
      "Onde houver o sinal de proibição de inverter o sentido de marcha (C12), também não a podes fazer, mesmo que o local pareça seguro."],
    "11.17": ["A marcha atrás só é permitida como manobra auxiliar ou de recurso e deve fazer-se lentamente e no menor trajeto possível.", "Código da Estrada, art. 46.º, n.º 1",
      { 1: "Mesmo com a via livre, a marcha atrás é só uma manobra de recurso, feita devagar e no menor trajeto possível.",
        2: "Os quatro piscas não autorizam a marcha atrás. Ela só é permitida como manobra auxiliar ou de recurso." },
      "Estacionar em paralelo é um uso normal da marcha atrás. Recuar uma longa distância para voltar a uma rua que passaste não é: segue em frente e volta por outro caminho."],
    "11.18": ["Nas autoestradas e nos seus acessos é proibido fazer marcha atrás, tal como inverter o sentido de marcha. Se passaste a saída, segues até à seguinte.", "Código da Estrada, art. 72.º (número a confirmar)",
      { 1: "Fazer marcha atrás na autoestrada, mesmo na berma, é proibido e muito perigoso: quem vem atrás circula a alta velocidade.",
        2: "Inverter o sentido de marcha na autoestrada é proibido e pode causar um choque com quem vem atrás ou de frente." },
      "Perder uma saída custa uns quilómetros. Planeia o percurso antes de arrancar e passa para a via da direita com antecedência."],
    "11.19": ["Se o cruzamento de dois veículos não for possível por haver um obstáculo na via, cede a passagem o condutor que tem de usar a parte esquerda da faixa de rodagem para o contornar.", "Código da Estrada, art. 33.º, n.º 1, alínea a)",
      { 1: "Não conta quem está mais perto: quem tem o obstáculo do seu lado é que cede.",
        2: "Chegar primeiro não dá prioridade aqui: cede quem tem de usar o lado esquerdo para contornar o obstáculo." },
      "Para atrás do pesado com distância suficiente para veres a estrada e saíres com facilidade depois de o ligeiro passar."],
    "11.20": ["Numa via estreita onde o cruzamento não é possível, cede, em regra, o condutor que chegar depois ao troço. Nas vias de inclinação acentuada, cede o condutor que desce.", "Código da Estrada, art. 33.º, n.º 1, alínea b)",
      { 1: "Em inclinação acentuada, é quem desce que cede: para quem sobe, parar e voltar a arrancar é mais difícil.",
        2: "A regra de quem chega depois vale nas vias estreitas sem inclinação acentuada. Numa descida acentuada, cedes tu." },
      "Se for preciso recuar até um sítio onde os dois caibam, recua o condutor que estiver mais perto desse sítio."],
    "8.2": ["A regra dos 2 segundos adapta-se à velocidade: quanto mais depressa, mais metros. Com chuva, deve ser mais.", "Boa prática (Art. 18.º, n.º 1 só exige «distância suficiente»)",
      { 1: "Um comprimento de carro é uma distância fixa e curta, que não acompanha a velocidade. A distância de segurança tem de aumentar com a velocidade.",
        2: "Uma distância fixa não serve, porque o espaço percorrido enquanto reages aumenta com a velocidade. A 90 km/h, 2 segundos são cerca de 50 metros." },
      "Para contar: quando o veículo da frente passar por um ponto fixo, diz «mil e um, mil e dois». Se chegares ao ponto antes de acabar, estás demasiado perto. Com piso molhado, conta pelo menos o dobro."]
  };
  var api = {};
  Object.keys(E).forEach(function (k) {
    api[k] = { explicacao: E[k][0], artigo: E[k][1], erradas: E[k][2] || {}, exemplo: E[k][3] || "" };
  });
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  else global.CartaXExplicacoes = api;
})(this);
